import { z } from "zod";
const zImageWidgetProps = z.object({
    src: z.string().url(),
    dark: z.string().url().or(z.literal("invert")).optional(),
    label: z.string().optional(),
    caption: z.string().optional(),
    size: z.enum(["s", "m", "l", "exact"]).default("m"),
    width: z.number().int().positive().optional(),
    height: z.number().int().positive().optional(),
    aspect: z.string().optional(),
    fullscreen: z.boolean().or(z.literal("allow")).default(false),
});
export function ImageWidget(define) {
    return define("Image")
        .props(zImageWidgetProps)
        .userEvents({
        click: [
            z.object({
                x: z.number(),
                y: z.number(),
                xr: z.number(),
                yr: z.number(),
                button: z.number(),
                altKey: z.boolean(),
                metaKey: z.boolean(),
                shiftKey: z.boolean(),
                ctrlKey: z.boolean(),
            }),
            null,
        ],
    })
        .render((props) => ({
        id: props.id,
        label: props.label,
        caption: props.caption,
        size: props.size,
        src: props.src,
        dark: props.dark,
        width: props.width,
        height: props.height,
        aspect: props.aspect,
        fullscreen: props.fullscreen,
    }));
}
